-- chair-step: inverse of read_lane_v2_b3_35_runtime_global_request — un-enrolls runtime.global_request from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'runtime' and table_name = 'global_request' and is_active);
select iam.apply_rls('runtime', 'global_request', (select token from platform.entity_types where schema_name = 'runtime' and table_name = 'global_request' and is_active), (select rls_variant from platform.entity_types where schema_name = 'runtime' and table_name = 'global_request' and is_active));
